def priority(item: float, bins: np.ndarray) -> np.ndarray:
    priorities = np.full_like(bins, -np.inf)
    valid_bins = bins >= item

    if np.any(valid_bins):
        remaining = bins[valid_bins] - item
        exact_match = remaining == 0
        if np.any(exact_match):
            priorities[valid_bins] = np.where(exact_match, 2, -np.inf)
        else:
            priorities[valid_bins] = 1 / (remaining + 1)

    return priorities

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    priorities = np.full_like(bins, -np.inf)
    valid_bins = bins >= item

    if np.any(valid_bins):
        remaining = bins[valid_bins] - item
        exact_match = remaining == 0
        if np.any(exact_match):
            priorities[valid_bins] = np.where(exact_match, np.inf, -np.inf)
        else:
            priorities[valid_bins] = -remaining

    return priorities
